commit a7df7651731bcf7a3308e26050c11f648de4c7f6
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Mon May 22 10:04:46 2017 +0100

    Fix buffer overrun in vcf_format.

    Fixes #537

    Also "fixed" the parser to prevent this from happening in the first
    place, but poorly as there is no way to return an error from
    bcf_hdr_register_hrec.

    The following minimal VCF triggered this crash. Note "dype".

        ##fileformat=VCFv4.1
        ##INFO=<ID=S,Number=1,dype=String,Description="blah">
        ##INFO=<ID=I,Number=1,Type=Integer,Description="blah">
        ##contig=<ID=chr1,length=249250621,assembly=b37>
        #CHROM      POS     ID      REF     ALT     QUAL    FILTER  INFO
        chr1        10327   .       T       C       .       .       S=foo;I=12345
        chr1        10327   .       T       C       .       .       S=foo;I=12345
---
 vcf.c | 13 ++++++++++++-
 1 file changed, 12 insertions(+), 1 deletion(-)

diff --git a/vcf.c b/vcf.c
index 522627e4..b71d3305 100644
--- a/vcf.c
+++ b/vcf.c
@@ -500,6 +500,11 @@ int bcf_hdr_register_hrec(bcf_hdr_t *hdr, bcf_hrec_t *hrec)
             if (var != BCF_VL_FIXED) num = 0xfffff;
         }
     }
+    if (strcmp(hrec->key, "INFO") == 0 && type == -1) {
+        if (hts_verbose >= 2)
+            fprintf(stderr, "[E::%s] An INFO field has no Type defined. Assuming String\n", __func__);
+        type = BCF_HT_STR;
+    }
     uint32_t info = ((((uint32_t)num) & 0xfffff)<<12 |
                      (var & 0xf) << 8 |
                      (type & 0xf) << 4 |
@@ -2533,6 +2538,11 @@ int vcf_format(const bcf_hdr_t *h, const bcf1_t *v, kstring_t *s)
             if ( !z->vptr ) continue;
             if ( !first ) kputc(';', s);
             first = 0;
+            if (z->key >= h->n[BCF_DT_ID]) {
+                fprintf(stderr, "[E::%s] invalid BCF, the INFO index is too large.\n", __func__);
+                errno = EINVAL;
+                return -1;
+            }
             kputs(h->id[BCF_DT_ID][z->key].key, s);
             if (z->len <= 0) continue;
             kputc('=', s);
@@ -2612,7 +2622,8 @@ int vcf_write(htsFile *fp, const bcf_hdr_t *h, bcf1_t *v)
 {
     int ret;
     fp->line.l = 0;
-    vcf_format1(h, v, &fp->line);
+    if (vcf_format1(h, v, &fp->line) != 0)
+        return -1;
