commit 1acad458ca8a30f6a3a0d98b1a2e8651c3f1bd44
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Mon Apr 10 09:33:51 2017 +0100

    Fix buffer overrun on corrupted data.

    Fixes #507

    (Note this bug has nothing to do with the c->l_extranul code.  It is
    simply that b->l_data (block_len-32) is smaller than c->l_qname.)
---
 sam.c | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/sam.c b/sam.c
index 46f0b652..dca2d58f 100644
--- a/sam.c
+++ b/sam.c
@@ -414,7 +414,9 @@ int bam_read1(BGZF *fp, bam1_t *b)
     if (bgzf_read(fp, b->data, c->l_qname) != c->l_qname) return -4;
     for (i = 0; i < c->l_extranul; ++i) b->data[c->l_qname+i] = '\0';
     c->l_qname += c->l_extranul;
-    if (bgzf_read(fp, b->data + c->l_qname, b->l_data - c->l_qname) != b->l_data - c->l_qname) return -4;
+    if (b->l_data < c->l_qname ||
+        bgzf_read(fp, b->data + c->l_qname, b->l_data - c->l_qname) != b->l_data - c->l_qname)
+        return -4;
     if (fp->is_be) swap_data(c, b->l_data, b->data, 0);
     return 4 + block_len;
 }
