Author: Rob Davies <rmd+git@sanger.ac.uk>
Date:   Mon Dec 5 20:00:01 2016 +0000

    Adds more CRAM decoder checks to prevent overrunning input buffers

    Converts more itf8_get() calls to safe_itf8_get().
    Adds a few extra tests to ensure running out of input is always spotted.
    Error messages in affected functions get tests for hts_verbose >= 1.
---
 cram/cram_codecs.c | 72 +++++++++++++++++++++++++++++++++++-------------------
 1 file changed, 47 insertions(+), 25 deletions(-)

diff --git a/cram/cram_codecs.c b/cram/cram_codecs.c
index 8cb27f4a..31d580ac 100644
--- a/cram/cram_codecs.c
+++ b/cram/cram_codecs.c
@@ -390,9 +390,12 @@ void cram_external_decode_free(cram_codec *c) {
 cram_codec *cram_external_decode_init(char *data, int size,
                                      enum cram_external_type option,
                                      int version) {
-    cram_codec *c;
+    cram_codec *c = NULL;
     char *cp = data;

+    if (size < 1)
+        goto malformed;
+
     if (!(c = malloc(sizeof(*c))))
        return NULL;

@@ -405,19 +408,22 @@ cram_codec *cram_external_decode_init(char *data, int size,
        c->decode = cram_external_decode_block;
     c->free   = cram_external_decode_free;

-    cp += itf8_get(cp, &c->external.content_id);
+    cp += safe_itf8_get(cp, data + size, &c->external.content_id);

-    if (cp - data != size) {
-       fprintf(stderr, "Malformed external header stream\n");
-       free(c);
-       return NULL;
-    }
+    if (cp - data != size)
+        goto malformed;

     c->external.type = option;
     c->external.b = NULL;
     c->reset = cram_external_decode_reset;

     return c;
+
+ malformed:
+    if (hts_verbose >= 1)
+        fprintf(stderr, "Malformed external header stream\n");
+    free(c);
+    return NULL;
 }

